#include <stdio.h>
int main(){
    int x[4] = {1,2,3,4};
    int k[3] = {1,0,-1};
    int out_len = 4 - 3 + 1; // 2
    int conv[2];
    for(int i=0;i<out_len;i++){
        conv[i]=0;
        for(int j=0;j<3;j++) conv[i] += x[i+j]*k[j];
    }
    // max‑pool with size 2, stride 2
    int pool[1];
    pool[0] = conv[0] > conv[1] ? conv[0] : conv[1];
    for(int i=0;i<out_len;i++) printf("%d\n", conv[i]);
    printf("%d\n", pool[0]);
    return 0;
}
